var i=[{title:`Waarom schouders verschillen`,text:`De schouder heeft een groot bewegingsbereik en leunt op veel spieren om stabiel te blijven. Reiken boven het hoofd, diepe persposities en snelle bewegingen kunnen van persoon tot persoon heel anders voelen. Een beweging die beperkt of pijnlijk is, zegt iets over welke oefeningen je kiest. Het bewijst niet dat je een bepaalde blessure hebt.`},{title:`Pas de oefening aan`,text:`Hindert een barbell overhead press je, probeer dan een dumbbellpers met neutrale grip, een ondersteunde row of een wall push-up. Verander de diepte of richting voordat je weerstand toevoegt. Trekoefeningen zijn een goede partner voor persen, maar geen vaste verhouding tussen duwen en trekken geneest schouderpijn.`},{title:`Controle en geleidelijke blootstelling`,text:`Gebruik terwijl je een beweging leert langzame, beheerste herhalingen, een comfortabel bereik en lichte gewichten. Schouderkracht opbouwen kan geleidelijk zwaarder werk vragen, maar die opbouw mag je klachten niet verergeren. Een rek forceren door pijn heen of steeds opnieuw zware lifts boven het hoofd testen brengt je er niet sneller.`},{title:`Waarschuwingssignalen`,text:`Vraag snel medisch advies bij ernstige pijn na een val, een arm die je niet kunt bewegen, een zichtbare misvorming, forse zwelling of nieuwe gevoelloosheid die niet weggaat. Ook klachten die niet verbeteren moeten door een professional worden bekeken.`},{title:`TrainUp gebruiken`,text:`Voeg je schouder toe onder beperkingen in Profiel, met notities, en houd je uitrustingslijst actueel. Het schema kiest dan alleen oefeningen die passen bij je beperkingen, uitrusting, niveau en coördinatie. Doet een oefening pijn tijdens een training, tik dan op “Ik voel pijn” om hem meteen te beëindigen. Hij blijft uit je schema’s tot je hem hervat in Profiel. Oefeningen op deze manier wisselen behandelt geen impingement, rotatorcuffziekte of een andere specifieke aandoening.`}];var t=[{label:`NHS: schouderpijn en waarschuwingssignalen`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};